pipeline {
  agent any
  stages {
    stage('Build') { steps { sh 'make build' } }
    stage('Test')  { steps { sh 'make test' } }
    stage('Deploy') {
      when { branch 'main' }
      steps { sh './deploy.sh' }
    }
  }
  post { failure { echo 'Build failed' } }
}

parallel {
  stage('Unit') { steps { sh 'make unit' } }
  stage('Lint') { steps { sh 'make lint' } }
}

