package main

import (
	"fmt"
	"net/http"
	"sync"
	"time"
)

func main() {
	urls := []string{"https://example.com", "https://example.org"}
	var wg sync.WaitGroup
	c := http.Client{Timeout: 5 * time.Second}
	for _, u := range urls {
		wg.Add(1)
		go func(u string) {
			defer wg.Done()
			r, err := c.Get(u)
			if err != nil {
				fmt.Println(u, "DOWN")
				return
			}
			defer r.Body.Close()
			fmt.Println(u, r.StatusCode)
		}(u)
	}
	wg.Wait()
}

